  if ((value.startsWith('dynAs<') && value.contains('->fnPtr('))) {
    final int firstParen = value.indexOf('(');
    if ((firstParen > 0)) {
      return value.substring((firstParen + 1), (value.length - 1));
    }
  }
  if ((value.contains('->fnPtr(') && !(value.startsWith('_box(')))) {
    final int callStart = value.indexOf('->fnPtr(');
    final String beforeCall = value.substring(0, callStart);
    if (((((beforeCall.isEmpty || beforeCall.endsWith(')')) || beforeCall.endsWith(']')) || beforeCall.contains('static_cast<')) || CppEmitter__isValidIdentifier(this_, beforeCall))) {
