bool CppEmitter__isValidIdentifier(AnyGC this__, String s) {
  final this_ = this__ as CppEmitterValue;
  if (s.isEmpty)   return false;
{
    StaticIterator<int> sync_for_iterator = StaticIterator(s.runes.iterator);
    for (; sync_for_iterator.moveNext(); ) {
      final int c = sync_for_iterator.current;
{
        final bool isAlpha = ((((c >= 65) && (c <= 90)) || ((c >= 97) && (c <= 122))) || (c == 95));
        final bool isDigit = ((c >= 48) && (c <= 57));
        if ((!(isAlpha) && !(isDigit)))         return false;
      }
    }
  }
  return true;
}

String CppEmitter__wrapValueByType(AnyGC this__, String value, DartType type) {
  final this_ = this__ as CppEmitterValue;
  if ((type is VoidType))   return value;
  if (((type is InterfaceType) && (type.classNode.name == 'Null')))   return 'nullptr';
