String? CppEmitter__unwrapAnyGCForComparison(AnyGC this__, String anyGCExpr, String otherOperand) {
  final this_ = this__ as CppEmitterValue;
  if ((StaticRegExp('^-?\\d+(LL)?$').hasMatch(otherOperand) || otherOperand.endsWith('LL'))) {
