String CppEmitter__extractStringFromBox(AnyGC this__, String args) {
  final this_ = this__ as CppEmitterValue;
  final RegExpMatch? stringBoxMatch = StaticRegExp('GC::allocateLocal\\(new StringBox\\((.+)\\)\\)$').firstMatch(args);
