  final RegExpMatch? otherBoxMatch = StaticRegExp('GC::allocateLocal\\(new (Int|Double|Bool)Box\\((.+)\\)\\)$').firstMatch(args);
  if (!((otherBoxMatch == null))) {
    final String innerValue = otherBoxMatch.group(2)!;
    return 'std::to_string(${innerValue})';
  }
  return args;
